1	import 'dart:async';
2	
3	import 'package:cerne/core/network/failure.dart';
4	import 'package:cerne/features/capture/domain/entities/recognition_failure.dart';
5	import 'package:cerne/features/capture/domain/repositories/audio_capture_repository.dart';
6	import 'package:cerne/features/capture/domain/repositories/photo_capture_repository.dart';
7	import 'package:cerne/features/capture/domain/usecases/save_audio_entry_usecase.dart';
8	import 'package:cerne/features/capture/domain/usecases/save_photo_entry_usecase.dart';
9	import 'package:cerne/features/capture/domain/usecases/save_text_entry_usecase.dart';
10	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
11	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_state.dart';
12	import 'package:flutter_bloc/flutter_bloc.dart';
13	
14	const _offlineMessage = 'Sem conexão. Conecte-se à internet para salvar.';
15	const _noSpeechMessage = 'Não foi possível identificar fala no áudio.';
16	const _genericAudioMessage = 'Não foi possível processar o áudio.';
17	const _noTextMessage = 'Não foi possível identificar texto na imagem.';
18	
19	/// One screen-scoped bloc for the whole Insertion Modal
20	/// (contracts/insertion-modal-bloc.md) — created fresh by `BlocProvider`
21	/// every time `showModalBottomSheet` opens the modal, which is what makes
22	/// FR-002's "reset every tab... each time the modal is freshly opened" true
23	/// without an explicit reset event.
24	class InsertionModalBloc
25	    extends Bloc<InsertionModalEvent, InsertionModalState> {
26	  InsertionModalBloc({
27	    required this._saveTextEntryUseCase,
28	    required this._audioCaptureRepository,
29	    required this._saveAudioEntryUseCase,
30	    required this._photoCaptureRepository,
31	    required this._savePhotoEntryUseCase,
32	  }) : super(const InsertionModalTexto()) {
33	    on<TabSelected>(_onTabSelected);
34	    on<TextDraftChanged>(_onTextDraftChanged);
35	    on<SaveTextSubmitted>(_onSaveTextSubmitted);
36	    on<AudioStartRequested>(_onAudioStartRequested);
37	    on<AudioTimerTicked>(_onAudioTimerTicked);
38	    on<AudioStopRequested>(_onAudioStopRequested);
39	    on<PhotoSourceSelected>(_onPhotoSourceSelected);
40	    on<RetryRequested>(_onRetryRequested);
41	    on<ModalClosed>(_onModalClosed);
42	  }
43	
44	  final SaveTextEntryUseCase _saveTextEntryUseCase;
45	  final AudioCaptureRepository _audioCaptureRepository;
46	  final SaveAudioEntryUseCase _saveAudioEntryUseCase;
47	  final PhotoCaptureRepository _photoCaptureRepository;
48	  final SavePhotoEntryUseCase _savePhotoEntryUseCase;
49	
50	  final _closeController = StreamController<void>.broadcast();
51	
52	  /// A one-shot side effect, not a state (FR-011, contracts/
53	  /// insertion-modal-bloc.md) — `InsertionModalPage` listens to this to pop
54	  /// the sheet. There is nothing to render for "success", so it never
55	  /// becomes a dedicated `InsertionModalState` case.
56	  Stream<void> get closeRequests => _closeController.stream;
57	
58	  String _textDraft = '';
59	  String? _pendingAudioPath;
60	  String? _pendingImagePath;
61	  Timer? _audioTicker;
62	
63	  /// Guards against discarding the same recording twice when both the
64	  /// explicit `ModalClosed` handler and `close()`'s disposal-time fallback
65	  /// (T073, for the swipe-down/tap-outside dismissal that bypasses
66	  /// `ModalClosed`) would otherwise race on the same still-recording state.
67	  bool _recordingDiscarded = false;
68	
69	  Future<void> _onTabSelected(
70	    TabSelected event,
71	    Emitter<InsertionModalState> emit,
72	  ) async {
73	    if (state is InsertionModalAudioRecording) {
74	      // Switching away mid-recording discards it (Edge Cases) — nothing
75	      // from an abandoned capture may survive (FR-008).
76	      _audioCaptureRepository.discard();
77	      _recordingDiscarded = true;
78	      _stopAudioTicker();
79	      _pendingAudioPath = null;
80	    }
81	
82	    switch (event.tab) {
83	      case CaptureTab.texto:
84	        emit(InsertionModalTexto(text: _textDraft));
85	      case CaptureTab.audio:
86	        emit(const InsertionModalAudioIdle());
87	      case CaptureTab.foto:
88	        emit(const InsertionModalFotoCaptura());
89	    }
90	  }
91	
92	  Future<void> _onAudioStartRequested(
93	    AudioStartRequested event,
94	    Emitter<InsertionModalState> emit,
95	  ) async {
96	    if (state is! InsertionModalAudioIdle) return;
97	
98	    final hasPermission = await _audioCaptureRepository.hasPermission();
99	    if (!hasPermission) {
100	      emit(const InsertionModalAudioPermissionDenied());
101	      return;
102	    }
103	    await _audioCaptureRepository.start();
104	    _recordingDiscarded = false;
105	    emit(const InsertionModalAudioRecording(elapsed: Duration.zero));
106	    _startAudioTicker();
107	  }
108	
109	  void _startAudioTicker() {
110	    _audioTicker?.cancel();
111	    _audioTicker = Timer.periodic(
112	      const Duration(seconds: 1),
113	      (_) => add(const AudioTimerTicked()),
114	    );
115	  }
116	
117	  void _stopAudioTicker() {
118	    _audioTicker?.cancel();
119	    _audioTicker = null;
120	  }
121	
122	  void _onTextDraftChanged(
123	    TextDraftChanged event,
124	    Emitter<InsertionModalState> emit,
125	  ) {
126	    _textDraft = event.text;
127	    emit(InsertionModalTexto(text: event.text));
128	  }
129	
130	  void _onAudioTimerTicked(
131	    AudioTimerTicked event,
132	    Emitter<InsertionModalState> emit,
133	  ) {
134	    final current = state;
135	    if (current is InsertionModalAudioRecording) {
136	      emit(
137	        InsertionModalAudioRecording(
138	          elapsed: current.elapsed + const Duration(seconds: 1),
139	        ),
140	      );
141	    }
142	  }
143	
144	  Future<void> _onSaveTextSubmitted(
145	    SaveTextSubmitted event,
146	    Emitter<InsertionModalState> emit,
147	  ) async {
148	    final current = state;
149	    final text = switch (current) {
150	      InsertionModalTexto(text: final t) => t,
151	      InsertionModalTextoFailure(text: final t) => t,
152	      _ => null,
153	    };
154	    if (text == null || text.trim().isEmpty) return;
155	
156	    emit(InsertionModalTextoSaving(text));
157	    final result = await _saveTextEntryUseCase(text);
158	    result.match(
159	      (failure) => emit(
160	        InsertionModalTextoFailure(text: text, message: failure.message),
161	      ),
162	      (entry) => _completeSave(),
163	    );
164	  }
165	
166	  Future<void> _onAudioStopRequested(
167	    AudioStopRequested event,
168	    Emitter<InsertionModalState> emit,
169	  ) async {
170	    if (state is! InsertionModalAudioRecording) return;
171	
172	    _stopAudioTicker();
173	    final path = await _audioCaptureRepository.stop();
174	    _pendingAudioPath = path;
175	    emit(const InsertionModalAudioSaving());
176	    await _saveAudio(path, emit);
177	  }
178	
179	  Future<void> _saveAudio(
180	    String audioFilePath,
181	    Emitter<InsertionModalState> emit,
182	  ) async {
183	    final result = await _saveAudioEntryUseCase(audioFilePath);
184	    result.match(
185	      (failure) =>
186	          emit(InsertionModalAudioFailure(_audioFailureMessage(failure))),
187	      (entry) {
188	        _pendingAudioPath = null;
189	        _completeSave();
190	      },
191	    );
192	  }
193	
194	  String _audioFailureMessage(SaveAudioFailure failure) => switch (failure) {
195	    SaveAudioOffline() => _offlineMessage,
196	    SaveAudioRecognitionFailed(:final recognitionFailure) =>
197	      switch (recognitionFailure) {
198	        EmptyRecognitionResult() => _noSpeechMessage,
199	        TranscriptionError() => _genericAudioMessage,
200	      },
201	    SaveAudioEntryCreationFailed(failure: final f) => f.message,
202	  };
203	
204	  Future<void> _onPhotoSourceSelected(
205	    PhotoSourceSelected event,
206	    Emitter<InsertionModalState> emit,
207	  ) async {
208	    if (state is InsertionModalFotoSaving) return;
209	
210	    String? path;
211	    try {
212	      path = await _photoCaptureRepository.pickImage(event.source);
213	    } catch (_) {
214	      emit(const InsertionModalFotoPermissionDenied());
215	      return;
216	    }
217	
218	    if (path == null) {
219	      emit(const InsertionModalFotoCaptura());
220	      return;
221	    }
222	
223	    _pendingImagePath = path;
224	    emit(const InsertionModalFotoSaving());
225	    await _savePhoto(path, emit);
226	  }
227	
228	  Future<void> _savePhoto(
229	    String imageFilePath,
230	    Emitter<InsertionModalState> emit,
231	  ) async {
232	    final result = await _savePhotoEntryUseCase(imageFilePath);
233	    result.match(
234	      (failure) =>
235	          emit(InsertionModalFotoFailure(_photoFailureMessage(failure))),
236	      (entry) {
237	        _pendingImagePath = null;
238	        _completeSave();
239	      },
240	    );
241	  }
242	
243	  String _photoFailureMessage(SavePhotoFailure failure) => switch (failure) {
244	    SavePhotoOffline() => _offlineMessage,
245	    SavePhotoRecognitionFailed(failure: final f) =>
246	      f is OcrNoTextFailure ? _noTextMessage : f.message,
247	    SavePhotoEntryCreationFailed(failure: final f) => f.message,
248	  };
249	
250	  Future<void> _onRetryRequested(
251	    RetryRequested event,
252	    Emitter<InsertionModalState> emit,
253	  ) async {
254	    final audioPath = _pendingAudioPath;
255	    final imagePath = _pendingImagePath;
256	    if (state is InsertionModalAudioFailure && audioPath != null) {
257	      emit(const InsertionModalAudioSaving());
258	      await _saveAudio(audioPath, emit);
259	    } else if (state is InsertionModalFotoFailure && imagePath != null) {
260	      emit(const InsertionModalFotoSaving());
261	      await _savePhoto(imagePath, emit);
262	    }
263	  }
264	
265	  void _onModalClosed(ModalClosed event, Emitter<InsertionModalState> emit) {
266	    if (state is InsertionModalAudioRecording) {
267	      _audioCaptureRepository.discard();
268	      _recordingDiscarded = true;
269	      _stopAudioTicker();
270	    }
271	    _pendingAudioPath = null;
272	    _pendingImagePath = null;
273	  }
274	
275	  void _completeSave() {
276	    if (!_closeController.isClosed) {
277	      _closeController.add(null);
278	    }
279	  }
280	
281	  @override
282	  Future<void> close() {
283	    if (state is InsertionModalAudioRecording && !_recordingDiscarded) {
284	      // `showModalBottomSheet`'s default swipe-down/tap-outside dismissal
285	      // bypasses `ModalClosed` entirely, so this is the only place that
286	      // reliably catches a still-recording mic at disposal time (FR-008).
287	      _audioCaptureRepository.discard();
288	      _recordingDiscarded = true;
289	      _pendingAudioPath = null;
290	    }
291	    _stopAudioTicker();
292	    unawaited(_closeController.close());
293	    return super.close();
294	  }
295	}
